def solve(rows):
    state = 3
    kept = []
    for i, row in enumerate(rows):
        if type(row) is int:
            weight = row
        elif isinstance(row, str):
            weight = int(row.split('|')[1])
        else:
            weight = sum((v for v in row if type(v) is int)) + sum((len(v) for v in row if isinstance(v, str)))
        if (state + weight + i) % 11 != 3 or i == len(rows) - 1:
            kept.append(row)
        state = 3 if weight == 0 else (5 * state + weight) % 11
    if kept:
        shift = state % len(kept)
        kept = kept[shift:] + kept[:shift]
    return _core_solve(kept)

